#!/usr/bin/env bash
# AKFC — Renommages de nommage + réparation des images des bios d'instructeur.
#  Schéma + migration 20261112000000_naming_and_instructor_bio_refs :
#   - PageReferencerKind : STAGE_* → SEMINAR_* ; + INSTRUCTOR_BIO
#   - TrashEntry.cloudinaryCreatedAt → providerCreatedAt
#   - table CloudinaryFolder → Folder, type CloudinaryFolderStatus → FolderStatus
#  Code :
#   - séminaires : SEMINAR_* ; corbeille : providerCreatedAt + audio reconnu (contrat inclus)
#   - bios : titre « Ma biographie d'instructeur » ; synchronisées à l'enregistrement
#     (saveMyInstructorBio), liens nettoyés à la
#     suppression d'un membre (users.delete), rattrapage des bios existantes au démarrage
#  Preuves avant commit (sinon TOUT est restauré) : prisma validate, generate, pnpm check,
#  puis sur la base LOCALE : migrate deploy + migrate diff VIDE (base = schéma).
# Prérequis : lot 3 de documentation appliqué.
# Usage : bash apply-naming-and-bio-media.sh
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
S="prisma/schema.prisma"
grep -q "Fichier de la médiathèque (finder), quel que soit son stockage." "$S" || { echo "ERREUR: applique d'abord le lot 3 (apply-schema-doc-lot3.sh)." >&2; exit 1; }
grep -q "INSTRUCTOR_BIO" "$S" && { echo "— déjà appliqué"; exit 0; }

MIG="prisma/migrations/20261112000000_naming_and_instructor_bio_refs"
SVC="packages/backend/src/modules/media/services/ensureInstructorBioMediaReferences.service.ts"
FILES=("$S"
  packages/backend/src/modules/seminars/router.ts
  packages/backend/src/modules/trash/services/trashToBin.service.ts
  packages/backend/src/modules/trash/services/listBin.service.ts
  packages/contracts/src/trash/trash-node.types.ts
  packages/contracts/src/trash/trash.dto.ts
  packages/backend/src/modules/users/router.ts
  apps/web/src/instrumentation.ts
  apps/web/src/features/social/InstructorBioEditor.tsx)
BK=/tmp/akfc_ren_backup; rm -rf "$BK"; mkdir -p "$BK"
for f in "${FILES[@]}"; do [ -f "$f" ] || { echo "ERREUR: $f introuvable." >&2; exit 1; }; mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; done
[ -e "$MIG" ] && { echo "ERREUR: $MIG existe déjà." >&2; exit 1; }
restore(){ for f in "${FILES[@]}"; do cp "$BK/$f" "$f"; done; rm -f "$SVC"; rm -rf "$MIG"; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }

W=/tmp/akfc_ren; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/schema_edit.py"
echo '' | base64 -d > "$W/code_edit.py"
echo '' | base64 -d > "$W/migration.sql"
echo '' | base64 -d > /tmp/akfc_ren_rollback.sql
echo '' | base64 -d > "$W/service.ts"

echo "== application =="
python3 "$W/schema_edit.py" "$S" "$S" || { restore; exit 1; }
mkdir -p "$MIG" && cp "$W/migration.sql" "$MIG/migration.sql" && echo "  ok  migration $MIG"
cp "$W/service.ts" "$SVC" && echo "  ok  $SVC"
python3 "$W/code_edit.py" . || { restore; exit 1; }

if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

PRISMA(){ pnpm exec prisma "$@" 2>/dev/null || pnpm --filter @workspace/backend exec prisma "$@"; }
echo "== prisma validate / generate =="
PRISMA validate --schema "$S" > /tmp/akfc_v.log 2>&1 || { tail -8 /tmp/akfc_v.log; restore; exit 1; }
PRISMA generate > /tmp/akfc_g.log 2>&1 || { tail -8 /tmp/akfc_g.log; restore; exit 1; }
echo "  ✅ schéma valide, client généré"
echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"

echo "== base LOCALE : migrate deploy + migrate diff (doit être VIDE) =="
DBURL=$(grep -E '^DATABASE_URL=' .env 2>/dev/null | head -1 | cut -d= -f2- | tr -d '"' || true)
HOST=$(python3 -c "import sys;from urllib.parse import urlparse;print(urlparse(sys.argv[1]).hostname or '')" "$DBURL" 2>/dev/null || true)
case "$HOST" in
  localhost|127.0.0.1|::1) echo "  base : $HOST (locale)";;
  *) echo "❌ DATABASE_URL (.env) ne pointe pas vers une base LOCALE (hôte « $HOST »). Par sécurité, rien n'est migré."; restore; exit 1;;
esac
if ! PRISMA migrate deploy > /tmp/akfc_md.log 2>&1; then
  echo "❌ migrate deploy a échoué :"; tail -12 /tmp/akfc_md.log
  echo "   Si la migration est marquée en échec : pnpm exec prisma migrate resolve --rolled-back 20261112000000_naming_and_instructor_bio_refs"
  restore; exit 1
fi
set +e
PRISMA migrate diff --from-url "$DBURL" --to-schema-datamodel "$S" --exit-code > /tmp/akfc_d.log 2>&1
code=$?; set -e
case $code in
  0) echo "  ✅ base migrée = schéma (aucune dérive)";;
  *) echo "❌ la base migrée ne correspond pas au schéma (code $code) :"; head -20 /tmp/akfc_d.log
     echo "   Annuler la migration sur la base LOCALE : psql \"<DATABASE_URL>\" -f /tmp/akfc_ren_rollback.sql"
     restore; exit 1;;
esac

git add -A
git commit -m "refactor(prisma): SEMINAR_*, providerCreatedAt, Folder ; fix: images des bios d'instructeur référencées" >/tmp/c.log 2>&1 && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }